		}
		stderrCh <- listingOutput{text: string(data)}
	}()
	result := proc.Wait()
	out := <-stdoutCh
	stderr := <-stderrCh
	if out.err != nil && out.err != io.EOF {
		return nil, agentwrap.NewError(agentwrap.ErrorHealth, "opencode models", "OpenCode model listing output could not be read", out.err)
	}
